<script setup>
import { computed } from 'vue';
import { sectionSpacing } from '../services/design.js';
import { useStorefront } from '../services/storefront.js';
import StoreDesignBlock from './StoreDesignBlock.vue';
import StoreActionLink from './StoreActionLink.vue';
import StoreSocialLinks from './StoreSocialLinks.vue';
import { StoreTextLayout } from '../services/storeNavigation.js';
const props = defineProps({ placement: { type: String, required: true } });
const sf = useStorefront();
const sections = computed(() => sf.design.value.sections.filter(section => section.enabled && section.placement === props.placement));
const style = section => ({ ...sectionSpacing(section), '--custom-columns': section.columns, '--custom-mobile-columns': Math.min(section.columns,2), '--custom-align': section.alignment });
</script>

<template>
  <section v-for="section in sections" :id="`store-section-${section.id}`" :key="section.id" class="store-section store-custom-section" :class="['custom-type-' + section.type, 'custom-variant-' + section.variant, 'custom-background-' + section.background, 'custom-align-' + section.alignment, {'custom-has-image':section.image, 'custom-full-bleed':section.fullWidth && !section.paddingX}]" :style="style(section)" :dir="StoreTextLayout.direction(section.textDirection)">
    <img v-if="section.variant === 'overlay' && section.image" :src="section.image" alt="" class="custom-overlay-image" loading="lazy"/>
    <div class="custom-section-intro">
      <div v-if="section.title || section.subtitle || section.body || section.buttonText" class="custom-section-copy"><p v-if="section.subtitle" class="custom-section-subtitle">{{section.subtitle}}</p><h2 v-if="section.title">{{section.title}}</h2><p v-if="section.body" class="custom-section-body">{{section.body}}</p><StoreActionLink v-if="section.buttonText" :target="section.buttonTarget" :label="section.buttonText" class="custom-section-action"/></div>
      <div v-if="section.image && section.variant !== 'overlay'" class="custom-section-image"><img :src="section.image" :alt="section.title || ''" loading="lazy"/></div>
    </div>
    <StoreSocialLinks v-if="section.type==='social'" :section="section"/>
    <div v-if="section.blocks.some(block => block.enabled)" class="custom-section-blocks"><StoreDesignBlock v-for="block in section.blocks.filter(block => block.enabled)" :key="block.id" :block="block"/></div>
  </section>
</template>

